package com.coxy.ghost.net

import android.content.Context
import android.util.Log

/**
 * Applies what [DeviceNameSignal] noticed, before the turn's prompt is assembled.
 *
 * Mirrors [com.coxy.ghost.personality.TraitNudger.applyFromText]: it runs first, so the reply that
 * acknowledges the naming is generated by a GHOST who already knows the name — and, more to the
 * point, so the acknowledgement is only produced when the name was genuinely stored.
 *
 * The returned line is appended to her reply rather than replacing it. That is deliberate: it is
 * evidence. Twice the model said "I've locked that in" having stored nothing, and the fix is not
 * only to store it but to make storing it visible.
 */
object DeviceNamer {

    private const val TAG = "DeviceNamer"

    /**
     * @return a short acknowledgement if a device was named, or null if the message did not name
     *   one, or named one that is not on the network.
     */
    suspend fun applyFromText(context: Context, text: String?): String? {
        val naming = DeviceNameSignal.detect(text) ?: return null

        // Only now is a scan worth paying for: detection is a regex over one message, and running
        // a network scan on every turn to catch a naming that almost never comes would be several
        // seconds added to every reply.
        val scan = LanScanner.scan(context)
        val devices = (scan as? LanScanner.Result.Scanned)?.devices ?: run {
            Log.i(TAG, "naming heard but the network is not visible right now")
            return null
        }

        val query = if (naming.target.startsWith(".")) {
            // ".24" is the last octet of this network, which is how people say it out loud.
            val prefix = LanScanner.wifiIpv4(context)?.substringBeforeLast('.') ?: return null
            "$prefix${naming.target}"
        } else naming.target

        val device = (DeviceMatcher.resolve(query, devices) as? DeviceMatcher.Resolution.Match)
            ?.device
            ?: run {
                Log.i(TAG, "naming heard for '$query' but nothing there answers to it")
                return null
            }

        val key = DeviceNames.set(context, device, naming.name)
        // Or the next command would still see the old label for the life of the cache.
        LanScanner.invalidate()
        Log.i(TAG, "named ${device.ip} \"${naming.name}\" as $key")

        return if (key.startsWith("mac:")) {
            "(Saved: ${device.ip} is \"${naming.name}\". That'll hold even if its address changes.)"
        } else {
            "(Saved: ${device.ip} is \"${naming.name}\" — by address only, so it may not hold if the router moves it.)"
        }
    }
}
